function GearHintUI:SetPCKey( keyTxt_ )
    assert( type(keyTxt_) == "string" )
    if isNotNull(self.pcTxt) then
        self.pcTxt.text = keyTxt_
    else
        printError("koko- 异常: prefab 没绑定 pcTxt ")
    end
end


